 //GETTING USER LOCATION , USER TYPE
 var idenlocationGr = new GlideRecordSecure('x_aleen_snguardian_identity_location')
 idenlocationGr.addQuery('identity',vaInputs.user_sys_id);
 idenlocationGr.query();
 var location = "";
 if(idenlocationGr.next()){
 location = idenlocationGr.location;
 vaVars.user_location = location;
 vaVars.user_type = idenlocationGr.identity.type;
 }

 //BADGE TYPE BASED ON SELECTED BADGE 
 vaVars.badge_to_replace = vaInputs.display_user_active_badges;
 var idenAssetGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset');
 idenAssetGr.addQuery('sys_id',vaVars.badge_to_replace);
 idenAssetGr.query();
 if(idenAssetGr.next()){
 vaVars.badge_type = idenAssetGr.getDisplayValue('asset.type.code'); //asset type code
 vaVars.badge_system = idenAssetGr.asset.system // system sys_id
 }

 //GET DT BADGE ACTION CONFIG - user location, user type, badge action , badge type
 //USER TYPE - ??? input or fetch using script
 vaVars.badge_action = "replace"
 var inputs = {};
 inputs['user_location'] = vaVars.user_location; // Reference, Sys ID of the record 
 inputs['user_type'] = vaVars.user_type; // Reference, Sys ID of the record 
 inputs['u_badge_type'] = vaVars.badge_type; // String 
 inputs['u_badge_action'] = vaVars.badge_action; // String 

 var dt = new sn_dt.DecisionTableAPI();
 var response = dt.getDecision('0d37c78833843650bf1221382e5c7bc7', inputs);

 var result_elements = response.result_elements;
 vaVars.dt_res_u_auto_badge_allocation = result_elements.u_auto_badge_allocation.getValue(); // True/False
 vaVars.dt_res_u_create_request = result_elements.u_create_request.getValue(); // True/False
 vaVars.dt_res_u_def_valid_from = result_elements.u_def_valid_from.getValue(); // True/False
 vaVars.dt_res_u_def_valid_to = result_elements.u_def_valid_to.getValue(); // Duration
 vaVars.dt_res_u_def_access = result_elements.u_def_access.getValue(); // True/False
 vaVars.dt_res_u_copy_access = result_elements.u_copy_access ; //True/False
 vaVars.dt_res_u_deactivate_old_badge = result_elements.u_deactivate_old_badge; //True/False

 var badgeTypeSysId = metadataGlideRecordHelper.getRecordSysIdByCode('x_aleen_snguardian_asset_type',vaVars.badge_type);

 //IF dt_res_u_auto_badge_allocation == 1
 if(vaVars.dt_res_u_auto_badge_allocation){
 var assetGr = new GlideRecordSecure('x_aleen_snguardian_asset');
 assetGr.addQuery('type.code',vaVars.badge_type); //code
 assetGr.addQuery('system',vaVars.badge_system); //sys_id
 assetGr.addQuery('status.code',"UNASSIGNED");
 assetGr.query();
 if(assetGr.next()){
 vaVars.new_asset_id = assetGr.getUniqueValue(); //sys_id
 }//IF NO BADGE IN INVENTORY


 }

 //HANDLE DEFAULT VALID FROM = 1, VALID TO !="" - timezone based
 //if vaVars.dt_res_u_def_valid_from == 1, set value of badge_valid_from
 if(vaVars.dt_res_u_def_valid_from == "1"){
 vaInputs.badge_valid_from = new GlideDateTime().getDisplayValue();
 }
 // if vaVars.dt_res_u_def_valid_to'' set value of badge_valid_to
 if("1970-01-01 00:00:00" != vaVars.dt_res_u_def_valid_to && "" != vaVars.dt_res_u_def_valid_to){
 vaInputs.badge_valid_to = new x_aleen_snguardian.TimeZoneUtil().getDurationDifference(vaVars.dt_res_u_def_valid_to, "add");
 }

 //ASK USER INPUT :: IF MANUAL, valid from ==0 , valid to ==0
 if( vaVars.dt_res_u_create_request == "0"){
 vaVars.submission_mode = "direct";
 }else{
 // vaVars.submission_mode = "request";
 vaVars.submission_mode = "direct";
